    "home.quote.layout": {en:"Workshop Layout",zh:"车间布局图",es:"Diseño del Taller",ru:"Планировка цеха",ar:"تخطيط الورشة",tr:"Atölye Düzeni",fr:"Plan d'atelier",pt:"Layout da Oficina",hi:"वर्कशॉप लेआउट",id:"Tata Letak Bengkel"},
