    "ind.food.li35": {en:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs stainless steel duct &mdash; decision framework</a>",zh:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">镀锌与不锈钢风管 &mdash; 决策框架</a>",es:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs acero inoxidable conducto &mdash; decision framework</a>",ru:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs нержавеющая сталь воздуховод &mdash; decision framework</a>",ar:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs فولاذ مقاوم للصدأ مجرى الهواء &mdash; decision framework</a>",tr:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs paslanmaz çelik kanal &mdash; decision framework</a>",fr:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs acier inoxydable conduit &mdash; decision framework</a>",pt:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs aço inoxidável duto &mdash; decision framework</a>",hi:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs स्टेनलेस स्टील डक्ट &mdash; decision framework</a>",id:"<a href=\"../insights/galvanized-vs-stainless-steel-duct.html\" data-i18n=\"footer.ins.galvanized\">Galvanized vs baja tahan karat saluran &mdash; decision framework</a>"},
    "ind.food.li36": {en:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",zh:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA密封等级详解</a>",es:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",ru:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",ar:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",tr:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",fr:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",pt:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",hi:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>",id:"<a href=\"../insights/smacna-seal-classes-explained.html\" data-i18n=\"footer.ins.smacna\">SMACNA seal classes explained</a>"},
